"use strict";

import { StyleSheet, UnistyleDependency } from '../../specs';
export const listener = ({
  dependencies,
  updateTheme,
  updateRuntime
}) => {
  const listensToTheme = dependencies.includes(UnistyleDependency.Theme);
  let theme = false, runtime = false, themeName = false, scheduled = false;
  const dispose = StyleSheet.addChangeListener(changedDependencies => {
    if (listensToTheme && changedDependencies.includes(UnistyleDependency.Theme)) theme = true;
    if (changedDependencies.some(dependency => dependencies.includes(dependency))) {
      runtime = true;
      if (changedDependencies.includes(UnistyleDependency.ThemeName)) themeName = true;
    }
    if (scheduled || !(theme || runtime)) return;
    scheduled = true;
    Promise.resolve().then(() => {
      scheduled = false;
      const t = theme, r = runtime, n = themeName;
      theme = runtime = themeName = false;
      if (t) updateTheme();
      if (r) updateRuntime(n);
    });
  });
  return () => dispose();
};
